// ── Invoice guardrail: deterministic compare of the extracted PDF against your books ──
// Runs AFTER the Merge node, so read with .first() (paired-item lineage breaks across merges).
const item      = $input.first().json;
const extracted = item.data || {};   // easybits Extractor wraps its output in a `data` envelope
const truth     = item;              // Google Sheets columns sit at the top level after the merge

// Fields to verify. `extracted` = field key in your easybits pipeline; `truth` = column in your Sheet.
// Keep these two name sets identical to the ones below or the compare silently skips them.
const FIELDS = [
  { label: 'Invoice number', extracted: 'invoice_number', truth: 'invoice_number', type: 'id',     required: true },
  { label: 'Customer name',  extracted: 'customer_name',  truth: 'customer_name',  type: 'text',   required: true },
  { label: 'IBAN',           extracted: 'iban',           truth: 'iban',           type: 'iban',   required: true },
  { label: 'VAT ID',         extracted: 'vat_id',         truth: 'vat_id',         type: 'id',     required: true },
  { label: 'Net total',      extracted: 'total_net',      truth: 'total_net',      type: 'amount', required: true, tolerance: 0.01 },
  { label: 'VAT amount',     extracted: 'vat_amount',     truth: 'vat_amount',     type: 'amount', required: true, tolerance: 0.01 },
  { label: 'Gross total',    extracted: 'total_gross',    truth: 'total_gross',    type: 'amount', required: true, tolerance: 0.01 },
  { label: 'Service period', extracted: 'service_period', truth: 'service_period', type: 'text',   required: false },
];

// Extractor returns the literal string "null" for empty fields; treat that as missing too.
function isMissing(v) {
  if (v === null || v === undefined) return true;
  const s = String(v).trim();
  return s === '' || s.toLowerCase() === 'null';
}

function normText(v) { return String(v).trim().replace(/\s+/g, ' ').toLowerCase(); }
function normId(v)   { return String(v).replace(/\s+/g, '').toUpperCase(); } // IBAN / invoice no / VAT id

// Parse money in either German (1.234,56) or English (1,234.56) format, strip currency symbols.
function parseAmount(v) {
  let s = String(v).replace(/[^\d.,-]/g, '');
  if (s === '') return null;
  const lastComma = s.lastIndexOf(',');
  const lastDot   = s.lastIndexOf('.');
  const decSep    = lastComma > lastDot ? ',' : '.';
  const thouSep   = decSep === ',' ? '.' : ',';
  s = s.split(thouSep).join('').replace(decSep, '.');
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
}

const mismatches = [];
const missing    = [];
const checked    = [];

for (const f of FIELDS) {
  const rawE = extracted[f.extracted];
  const rawT = truth[f.truth];
  const eMissing = isMissing(rawE);
  const tMissing = isMissing(rawT);

  if (f.required && tMissing) { missing.push(f.label + ' (no value found in your books)'); continue; }
  if (f.required && eMissing) { missing.push(f.label + ' (missing on the invoice)');       continue; }
  if (eMissing && tMissing)   { continue; } // optional field absent on both sides

  let match;
  if (f.type === 'amount') {
    const en = parseAmount(rawE), tn = parseAmount(rawT);
    match = en !== null && tn !== null && Math.abs(en - tn) <= (f.tolerance ?? 0.01);
  } else if (f.type === 'iban' || f.type === 'id') {
    match = normId(rawE) === normId(rawT);
  } else {
    match = normText(rawE) === normText(rawT);
  }

  checked.push(f.label);
  if (!match) mismatches.push({ field: f.label, on_invoice: String(rawE), in_books: String(rawT) });
}

const approved = mismatches.length === 0 && missing.length === 0;

return [{
  json: {
    approved,
    verdict: approved ? 'PASS' : 'FAIL',
    invoice_number: truth.invoice_number ?? extracted.invoice_number ?? null,
    reason: approved
      ? 'All checked fields match your books.'
      : 'Discrepancies found. Do not send.',
    mismatches,
    missing,
    checked_fields: checked,
  }
}];
